const body = $json.body ?? $json;

for (const required of ['candidate_profile', 'job']) {
  if (!body[required]) throw new Error(`Missing required field: ${required}`);
}

const profile = body.candidate_profile;
const positive = body.positive_examples ?? [];
const negative = body.negative_examples ?? [];
const job = body.job;

const prompt = `You are a career matching engine for one candidate.

SCORING PRIORITY
1. Explicit negative examples and avoid preferences.
2. Explicit positive examples and preferred roles.
3. Candidate skills and experience.
4. Location and seniority fit.
5. Transferable skills.

Do not inflate a score merely because a job is in telecom.

Score meaning:
90-100 exceptional fit
80-89 strong fit
70-79 reasonable fit
55-69 borderline
below 55 poor fit

Candidate profile:
${JSON.stringify(profile, null, 2)}

Jobs the candidate likes:
${JSON.stringify(positive, null, 2)}

Jobs the candidate dislikes:
${JSON.stringify(negative, null, 2)}

Job to evaluate:
${JSON.stringify(job, null, 2)}

Evaluate the job and call the record_job_match tool exactly once with the final result.`;

const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    score: { type: 'integer', minimum: 0, maximum: 100 },
    verdict: { type: 'string', enum: ['EXCELLENT','STRONG','POSSIBLE','WEAK','REJECT'] },
    matching_reasons: { type: 'array', items: { type: 'string' }, maxItems: 5 },
    gaps: { type: 'array', items: { type: 'string' } },
    red_flags: { type: 'array', items: { type: 'string' } },
    inferred_role_family: { type: 'string' },
    recommended_action: { type: 'string', enum: ['APPLY','REVIEW','SKIP'] }
  },
  required: ['score','verdict','matching_reasons','gaps','red_flags','inferred_role_family','recommended_action']
};

const request = {
  model: body.model || 'claude-haiku-4-5',
  max_tokens: 1200,
  messages: [{ role: 'user', content: prompt }],
  tools: [{
    name: 'record_job_match',
    description: 'Return the final structured assessment of how well this job matches the candidate.',
    input_schema: schema
  }],
  tool_choice: { type: 'tool', name: 'record_job_match' }
};

return [{ json: { request, source_job: job } }];

const r = $json;
const toolUse = (r.content ?? []).find(item => item.type === 'tool_use' && item.name === 'record_job_match');
if (!toolUse?.input) throw new Error('Anthropic response did not contain record_job_match tool output');
return [{ json: { ...toolUse.input, scored_at: new Date().toISOString(), model: r.model, usage: r.usage ?? {} } }];
